-- Category labels required by the node mappings in docker/db/knowledge-graph.sql.
-- A fresh volume runs schema.sql then knowledge-graph.sql, but nothing seeds
-- `category`, so every INSERT ... JOIN `category` there inserts nothing and
-- knowledge_node_category stays empty. Apply this file before knowledge-graph.sql.
-- Literals are hex encoded so the client character set cannot corrupt them.
-- Idempotent: only inserts labels that are missing.
SET NAMES utf8mb4;
